                      'HEADS' if 'SELECT cid FROM heads' in sql else 'LEGACY_PRESENCE' if 'EXISTS(SELECT 1 FROM titles' in sql else
                      'V2_KEYS' if 'SELECT i.sid,i.cid' in sql else 'LEGACY_KEYS' if 'SELECT t.sid,t.cid' in sql else 'PAYLOAD')
        try:
